<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {UserRound,MapPin,CreditCard,LockKeyhole,Plus} from 'lucide-vue-next';import {api,idr} from '../api';import {useCart,useSession,useUi} from '../stores';const cart=useCart(),session=useSession(),ui=useUi(),router=useRouter(),addresses=ref<any[]>([]),addressId=ref(''),error=ref(''),loading=ref(true),placing=ref(false),showForm=ref(false),form=ref({recipientName:'',phone:'',addressLine:'',city:'',province:'',postalCode:'',isDefault:true});onMounted(async()=>{if(!session.user){await session.load();if(!session.user)return router.push('/login')}try{await cart.load();addresses.value=await api('/addresses');addressId.value=addresses.value.find(a=>a.isDefault)?.id??addresses.value[0]?.id??'';showForm.value=!addresses.value.length}catch(e:any){error.value=e.message}finally{loading.value=false}});async function saveAddress(){try{const address=await api<any>('/addresses',{method:'POST',body:JSON.stringify(form.value)});addresses.value.push(address);addressId.value=address.id;showForm.value=false;ui.toast('Shipping address saved')}catch(e:any){error.value=e.message}}async function place(){placing.value=true;error.value='';try{const order=await api<any>('/checkout/orders',{method:'POST',body:JSON.stringify({addressId:addressId.value,idempotencyKey:crypto.randomUUID()})});await cart.load();router.push(`/checkout/success/${order.orderNumber}`)}catch(e:any){error.value=e.message}finally{placing.value=false}}</script>
<template><main class="checkout-page"><div class="container"><header class="checkout-header"><h1>Checkout</h1><p>Complete your shipping and payment details</p></header><p v-if="error" class="alert error">{{error}}</p><div v-if="loading" class="checkout-grid"><div class="skeleton checkout-skeleton"></div><div class="skeleton checkout-skeleton"></div></div><div v-else class="checkout-grid"><div class="checkout-forms"><section class="surface checkout-card"><h2><UserRound :size="17"/> 1. Contact Information</h2><div class="field-grid"><label>Full Name<input :value="session.user?.name" disabled/></label><label>Email Address<input :value="session.user?.email" disabled/></label></div></section><section class="surface checkout-card"><div class="card-heading"><h2><MapPin :size="17"/> 2. Shipping Address</h2><button v-if="addresses.length" @click="showForm=!showForm"><Plus :size="14"/> Add new</button></div><div v-if="addresses.length&&!showForm" class="address-options"><label v-for="a in addresses" :key="a.id" :class="{selected:addressId===a.id}"><input v-model="addressId" type="radio" :value="a.id"/><span><b>{{a.recipientName}}</b><small>{{a.addressLine}}, {{a.city}}, {{a.province}} {{a.postalCode}}</small><small>{{a.phone}}</small></span><em v-if="a.isDefault">Default</em></label></div><form v-if="showForm" class="field-grid" @submit.prevent="saveAddress"><label>Recipient Name<input v-model="form.recipientName" required minlength="2"/></label><label>Phone Number<input v-model="form.phone" required minlength="8"/></label><label class="full">Street Address<input v-model="form.addressLine" required minlength="8"/></label><label>City<input v-model="form.city" required/></label><label>Province<input v-model="form.province" required/></label><label>Postal Code<input v-model="form.postalCode" required/></label><label class="check"><input v-model="form.isDefault" type="checkbox"/> Set as default address</label><div class="form-actions"><button v-if="addresses.length" type="button" class="btn-secondary" @click="showForm=false">Cancel</button><button class="btn-primary">Save Address</button></div></form></section><section class="surface checkout-card"><h2><CreditCard :size="17"/> 3. Payment Method</h2><label class="payment-option selected"><input type="radio" checked/><span><b>Demo Secure Payment</b><small>Simulate success or failure after placing your order.</small></span></label></section></div><aside class="surface order-summary"><h2>Order Summary</h2><article v-for="item in cart.cart?.items" :key="item.id"><img :src="item.product.images[0]?.imageUrl"/><div><b>{{item.product.name}}</b><small>Qty: {{item.quantity}}</small></div><strong>{{idr(Number(item.product.price)*item.quantity)}}</strong></article><div class="summary-lines"><p><span>Subtotal</span><b>{{idr(cart.total)}}</b></p><p><span>Shipping</span><b>{{idr(25000)}}</b></p><p><span>Discount</span><b>− {{idr(0)}}</b></p><p class="grand"><span>Total</span><strong>{{idr(cart.total+25000)}}</strong></p></div><button class="btn-primary wide" :disabled="!addressId||!cart.cart?.items.length||placing" @click="place"><LockKeyhole :size="15"/> {{placing?'Processing…':'Place Order'}}</button><small class="secure-note">Your order is protected by server-side stock validation.</small></aside></div></div></main></template>
